import{_ as a,o as n,c as o,aa as t}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/en/diary/en_nepracovniden.jpg",s="/buildary-help-preview/media/en/diary/en_nepracovni_dny.jpg",k=JSON.parse('{"title":"Non-Working Days","description":"","frontmatter":{"title":"Non-Working Days","wiki":"en:diary:nonworkingdays"},"headers":[],"relativePath":"en/diary/nonworkingdays.md","filePath":"en/diary/nonworkingdays.md","lastUpdated":1794388980000}'),r={name:"en/diary/nonworkingdays.md"};function d(c,e,l,y,g,p){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="non-working-days" tabindex="-1">Non-Working Days <a class="header-anchor" href="#non-working-days" aria-label="Permalink to &quot;Non-Working Days&quot;">​</a></h1><figure class="shot" style="--w:400px;"><img src="'+i+'" alt="" width="400" loading="lazy"></figure><p>In Buildary, the term <strong>“Non-Working Day”</strong> refers to a day that contains no data but is nevertheless a valid state. Examples include weekends or technological breaks in construction work.</p><p>When you select a day, the drop-down menu on the right side of the window header contains the <strong>“Non-Working Day”</strong> option. This option allows you to lock the selected day or a range of days without any data being entered. A locked Non-Working Day allows subsequent days to be locked and signed.</p><img src="'+s+'" alt="" width="400" loading="lazy"><p>A Non-Working Day can be changed back to a working day using the same procedure. However, if the Non-Working Day has already been locked with an electronic signature, it <strong>CANNOT</strong> be changed back to a working day.</p><p>Non-Working Days are indicated by a <strong>gray underline</strong> in the header.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Buildary does not allow you to lock a day with an electronic signature if it is preceded by a day that has not been electronically signed or has not been locked as a Non-Working Day. This is because the pages of the construction diary must be numbered sequentially.</p><p>Therefore, if a day is empty because no work was carried out on the construction site, mark it as a <strong>“Non-Working Day”</strong>. Otherwise, you will not be able to lock the subsequent days.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A day that has already been signed cannot be changed to Non-Working Day status.</p></div>',9)])])}const u=a(r,[["render",d]]);export{k as __pageData,u as default};
